using System.Collections.Generic;
using UnityEngine;
namespace Kamilunavo.RepairEmpire.Visuals {
 // These are actual scene models, photographed by one scene-owned camera. No bitmap stands in for gameplay.
 public sealed class ServiceSceneArt:MonoBehaviour {
  public const int PreviewLayer=30;
  readonly Dictionary<string,RenderTexture> images=new();Camera camera;Transform studio;RenderTexture repairImage;string repairKey;int repairPhase=-1,repairContacts=-1;GameObject repairModel;
  static Material Ceramic=>MeshArt.Mat("FixturePorcelain",new(.92f,.93f,.89f));
  static Material Navy=>MeshArt.Mat("FixtureNavy",new(.025f,.065f,.11f));
  static Material Orange=>MeshArt.Mat("FixtureOrange",new(1,.34f,.055f));
  static Material Metal{get{var m=MeshArt.Mat("FixtureChrome",new(.68f,.76f,.79f));m.SetFloat("_Metallic",.82f);m.SetFloat("_Glossiness",.86f);return m;}}
  public static string VisualKey(string id){if(id=="toilet"||id=="switch"||id=="sink"||id=="heating"||id=="climate")return id;if(id.StartsWith("call-1-"))return "switch";if(id.StartsWith("call-2-"))return "heating";if(id.StartsWith("call-3-"))return "climate";return "faucet";}
  void Ensure(){if(camera!=null)return;studio=new GameObject("Isolated service photo studio").transform;studio.SetParent(transform,false);studio.localPosition=new(0,-1000,0);var go=new GameObject("Service photography camera",typeof(Camera));go.transform.SetParent(studio,false);camera=go.GetComponent<Camera>();camera.enabled=false;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new(.69f,.65f,.58f);camera.cullingMask=1<<PreviewLayer;camera.nearClipPlane=.05f;camera.farClipPlane=40;camera.fieldOfView=35;camera.allowHDR=false;camera.allowMSAA=true;
   var key=new GameObject("Service softbox",typeof(Light));key.transform.SetParent(studio,false);key.transform.localPosition=new(-2,4,-2);key.transform.LookAt(studio.position+Vector3.up*.5f);var light=key.GetComponent<Light>();light.type=LightType.Spot;light.range=12;light.spotAngle=90;light.intensity=1.45f;light.color=new(.94f,.97f,1);light.cullingMask=1<<PreviewLayer;light.shadows=LightShadows.Soft;
  }
  RenderTexture Target(string name,int w,int h){var target=new RenderTexture(w,h,16,RenderTextureFormat.ARGB32){name=name,antiAliasing=2};target.Create();ArtLifetime.Own(gameObject,target);return target;}
  void Photograph(GameObject model,RenderTexture target,bool workshop=false){SetLayer(model.transform);OwnStudioMaterials(model);var previousTarget=camera.targetTexture;camera.targetTexture=target;camera.aspect=(float)target.width/target.height;camera.transform.localPosition=workshop?new Vector3(7,4.1f,-9):new Vector3(1.55f,1.50f,-2.55f);camera.transform.LookAt(studio.position+(workshop?new Vector3(0,1.25f,0):new Vector3(0,.48f,0)));camera.fieldOfView=workshop?43:35;var previousActive=RenderTexture.active;try{camera.Render();}finally{camera.targetTexture=previousTarget;RenderTexture.active=previousActive;model.SetActive(false);}}
  void OwnStudioMaterials(GameObject model){foreach(var renderer in model.GetComponentsInChildren<MeshRenderer>()){var material=renderer.sharedMaterial;if(material==null)continue;string name=material.name;if(name.StartsWith("Fixture")||name.StartsWith("Bathroom")||name=="ServiceCloth"||name=="WaterHighlight"||name=="ValveBrass"||name=="SoapAmber"||name=="SwitchRocker"||name=="WorkshopPlywood"||name=="WorkshopPlaster")ArtLifetime.Own(gameObject,material);}}
  static void SetLayer(Transform root){root.gameObject.layer=PreviewLayer;foreach(Transform child in root)SetLayer(child);}
  public Texture Thumbnail(string id){Ensure();string key=VisualKey(id);if(images.TryGetValue(key,out var image))return image;image=Target("Service image "+key,256,256);var model=BuildFixture(studio,key,-1);Photograph(model,image);images.Add(key,image);DestroyModel(model);return image;}
  public Texture WorkshopImage(){Ensure();if(images.TryGetValue("workshop",out var image))return image;image=Target("Workshop hero image",768,432);var model=BuildWorkshop(studio);Photograph(model,image,true);images.Add("workshop",image);DestroyModel(model);return image;}
  public Texture RepairImage(string id,int phase,int contacts=0){Ensure();string key=VisualKey(id);if(repairImage==null)repairImage=Target("Live modeled repair scene",640,640);if(repairKey==key&&repairPhase==phase&&repairContacts==contacts)return repairImage;if(repairModel!=null)DestroyModel(repairModel);repairModel=BuildFixture(studio,key,phase,contacts);Photograph(repairModel,repairImage);repairKey=key;repairPhase=phase;repairContacts=contacts;return repairImage;}
  void OnDestroy(){if(camera!=null)camera.targetTexture=null;foreach(var target in images.Values)if(target!=null)target.Release();if(repairImage!=null)repairImage.Release();}
  static void DestroyModel(GameObject model){if(Application.isPlaying)Destroy(model);else DestroyImmediate(model);}
  public static GameObject BuildFixture(Transform parent,string id,int phase,int contacts=0){string key=VisualKey(id);var root=new GameObject("Modeled "+key+" service scene");root.transform.SetParent(parent,false);var stone=MeshArt.Mat("BathroomWarmStone",new(.72f,.67f,.57f));var grout=MeshArt.Mat("BathroomGrout",new(.47f,.45f,.39f));
   MeshArt.BevelBox(root.transform,"Stone counter",new(0,-.11f,0),new(1.9f,.17f,1.4f),.025f,stone);MeshArt.Box(root.transform,"Tiled customer wall",new(0,.8f,.57f),new(2.1f,1.8f,.1f),stone);
   for(int i=0;i<5;i++)MeshArt.Box(root.transform,"Tile vertical joint",new(-.9f+i*.45f,.8f,.51f),new(.005f,1.8f,.005f),grout);for(int i=0;i<5;i++)MeshArt.Box(root.transform,"Tile horizontal joint",new(0,-.05f+i*.4f,.51f),new(2.1f,.005f,.005f),grout);
   var fixture=new GameObject("Service fixture").transform;fixture.SetParent(root.transform,false);
   if(key=="faucet"||key=="sink")Faucet(fixture,phase,key=="sink",contacts);else if(key=="toilet")Toilet(fixture,phase);else if(key=="switch")Switch(fixture,phase,contacts);else if(key=="heating")Radiator(fixture,phase);else Climate(fixture,phase);
   if(key!="toilet"){if(key=="switch")Screwdriver(root.transform,new(.52f,.035f,-.30f));else Wrench(root.transform,new(.52f,.035f,-.30f));MeshArt.BevelBox(root.transform,"Folded service cloth",new(-.62f,.035f,.22f),new(.34f,.09f,.40f),.035f,MeshArt.Mat("ServiceCloth",new(.11f,.32f,.44f)));}
   if(key=="faucet"||key=="sink"){MeshArt.Lathe(root.transform,"Soap bottle",new[]{0f,.22f,.32f,.36f},new[]{.07f,.07f,.055f,.035f},16,MeshArt.Mat("SoapAmber",new(.38f,.23f,.12f)),Vector3.one).transform.localPosition=new(.62f,0,.38f);MeshArt.BevelBox(root.transform,"Soap dispenser",new(.63f,.40f,.34f),new(.16f,.035f,.05f),.01f,Metal);}
   return root;
  }
  static void Faucet(Transform root,int phase,bool sink,int contacts){
   MeshArt.Lathe(root,"Porcelain basin",new[]{-.065f,-.01f,.025f,.04f,.03f,-.04f},new[]{.13f,.26f,.46f,.48f,.41f,.16f},40,Ceramic,new(1.6f,1,1.1f)).transform.localPosition=new(0,0,-.19f);MeshArt.Lathe(root,"Basin drain",new[]{0f,.009f,.017f,.017f},new[]{0f,.052f,.052f,0f},24,Metal,Vector3.one).transform.localPosition=new(0,-.025f,-.20f);
   var mount=MeshArt.Lathe(root,"Faucet mounting flange",new[]{0f,.018f,.038f,.06f},new[]{.12f,.13f,.11f,.085f},32,Metal,Vector3.one);mount.transform.localPosition=new(-.13f,.04f,.22f);
   var body=MeshArt.Lathe(root,"Curved chrome faucet body",new[]{0f,.06f,.16f,.28f,.37f},new[]{.085f,.075f,.065f,.084f,.086f},32,Metal,Vector3.one);body.transform.localPosition=new(-.13f,.09f,.22f);
   var points=new List<Vector3>();for(int i=0;i<=14;i++){float a=i*Mathf.PI/14;points.Add(new(-.13f,.34f+Mathf.Sin(a)*.29f,.22f-(1-Mathf.Cos(a))*.21f));}MeshArt.Tube(root,"Curved chrome spout",points.ToArray(),.052f,Metal,24);MeshArt.Lathe(root,"Aerator outlet",new[]{0f,.035f,.05f},new[]{.051f,.055f,.049f},24,Navy,Vector3.one).transform.localPosition=new(-.13f,.305f,-.20f);
   bool replace=phase==1;MeshArt.BevelBox(root,"Mixer control cap",new(-.13f,replace?.74f:.47f,.22f),new(.18f,.075f,.16f),.035f,Metal);MeshArt.BevelBox(root,"Mixer lever",new(-.13f,replace?.79f:.52f,.115f),new(.06f,.035f,.31f),.013f,Metal);
   var brass=MeshArt.Mat("ValveBrass",new(.69f,.46f,.14f));MeshArt.Lathe(root,"Visible valve cartridge",new[]{0f,.075f,.11f},new[]{.055f,.055f,.038f},16,brass,Vector3.one).transform.localPosition=new(-.13f,.46f,.22f);
   var washer=MeshArt.Ring(root,"Replacement washer",.076f,.023f,replace&&contacts<3?.66f:.455f,Navy,40);washer.transform.localPosition=new(replace&&contacts==2?.16f:-.13f,0,.22f);if(replace){var halo=MeshArt.Ring(root,"Orange replacement focus",.113f,.008f,.66f,Orange,40);halo.transform.localPosition=new(-.13f,0,.22f);}
   if(phase==2||phase<0)MeshArt.Tube(root,"Water test stream",new[]{new Vector3(-.13f,.31f,-.2f),new Vector3(-.13f,.03f,-.2f)},.009f,MeshArt.Mat("WaterHighlight",new(.43f,.75f,.86f)),10);
   if(sink)MeshArt.Ring(root,"Drain service target",.08f,.013f,.013f,Orange,32).transform.localPosition=new(0,0,-.20f);
  }
  static void Toilet(Transform root,int phase){root.localScale=Vector3.one*.84f;MeshArt.Lathe(root,"Toilet pedestal",new[]{0f,.13f,.42f,.50f},new[]{.23f,.20f,.18f,.32f},32,Ceramic,new(1,1,1.3f)).transform.localPosition=new(0,-.07f,-.12f);MeshArt.Lathe(root,"Toilet bowl",new[]{.31f,.38f,.57f,.61f,.60f,.40f},new[]{.20f,.34f,.37f,.38f,.30f,.15f},40,Ceramic,new(1,1,1.35f)).transform.localPosition=new(0,0,-.17f);var seat=MeshArt.Ring(root,"Toilet seat",.375f,.075f,.65f,Ceramic,48);seat.transform.localScale=new(1,1,1.35f);seat.transform.localPosition=new(0,0,-.17f);MeshArt.BevelBox(root,"Toilet cistern",new(0,.86f,.28f),new(.74f,.72f,.30f),.065f,Ceramic);MeshArt.BevelBox(root,"Cistern lid",new(0,phase==1?1.40f:1.25f,.28f),new(.79f,.065f,.35f),.023f,Ceramic);MeshArt.BevelBox(root,"Flush button",new(0,phase==1?1.44f:1.29f,.28f),new(.15f,.015f,.06f),.005f,Metal);if(phase==1){MeshArt.Tube(root,"Flush valve",new[]{new Vector3(0,.90f,.28f),new Vector3(0,1.35f,.28f)},.07f,Orange);}}
  static void Switch(Transform root,int phase,int contacts){var plate=MeshArt.BevelBox(root,"Switch faceplate",new(0,.71f,.12f),new(.65f,.85f,.09f),.045f,Ceramic);MeshArt.BevelBox(root,"Switch shadow reveal",new(0,.71f,.18f),new(.72f,.92f,.05f),.015f,Navy);MeshArt.BevelBox(root,"Rocker switch",phase==1?new Vector3(-.58f,.025f,-.27f):new Vector3(0,.70f,.035f),new(.34f,.40f,.07f),.025f,MeshArt.Mat("SwitchRocker",new(.33f,.31f,.26f))).transform.localRotation=phase==1?Quaternion.Euler(90,0,-20):Quaternion.Euler(-9,0,0);foreach(float y in new[]{.38f,1.04f}){MeshArt.Oval(root,"Faceplate screw",new(0,y,.061f),new(.042f,.042f,.012f),Metal);MeshArt.Box(root,"Screw slot",new(0,y,.05f),new(.025f,.004f,.006f),Navy);}if(phase==1)for(int i=0;i<4;i++)MeshArt.Oval(root,"Electrical contact "+i,new((i%2-.5f)*.13f,.60f+(i/2)*.16f,-.03f),new(.04f,.04f,.015f),i<contacts?Metal:Orange);}
  static void Radiator(Transform root,int phase){for(int i=0;i<10;i++)MeshArt.BevelBox(root,"Radiator modeled fin",new(-.46f+i*.10f,.58f,.14f),new(.075f,.84f,.20f),.027f,Ceramic);foreach(float y in new[]{.20f,.96f})MeshArt.Tube(root,"Heating header",new[]{new Vector3(-.5f,y,.14f),new Vector3(.5f,y,.14f)},.048f,Metal);MeshArt.Tube(root,"Service heating valve",new[]{new Vector3(.52f,.2f,.14f),new Vector3(.68f,.2f,.14f),new Vector3(.68f,.05f,.14f)},.035f,Metal);MeshArt.Oval(root,"Thermostat knob",new(.65f,.28f,.14f),new(.15f,.18f,.15f),phase==1?Orange:Ceramic);}
  static void Climate(Transform root,int phase){MeshArt.BevelBox(root,"Climate enclosure",new(0,.75f,.15f),new(1.15f,.48f,.28f),.055f,Ceramic);for(int i=0;i<7;i++)MeshArt.Box(root,"Climate grille louvre",new(0,.60f+i*.025f,-.008f),new(.90f,.012f,.035f),Navy);MeshArt.BevelBox(root,"Climate filter",new(0,phase==1?.38f:.76f,phase==1?-.16f:.05f),new(.84f,.26f,.028f),.012f,phase==1?Orange:Ceramic);MeshArt.Oval(root,"Climate status lamp",new(.45f,.89f,-.003f),new(.033f,.02f,.008f),Orange);}
  static void Screwdriver(Transform parent,Vector3 position){var root=new GameObject("Insulated service screwdriver").transform;root.SetParent(parent,false);root.localPosition=position;root.localRotation=Quaternion.Euler(0,-25,0);MeshArt.BevelBox(root,"Orange insulated screwdriver handle",new(0,.03f,-.16f),new(.09f,.075f,.25f),.028f,Orange);MeshArt.Tube(root,"Screwdriver steel shaft",new[]{new Vector3(0,.03f,-.03f),new Vector3(0,.03f,.23f)},.013f,Metal,12);MeshArt.Box(root,"Screwdriver slotted tip",new(0,.03f,.245f),new(.024f,.006f,.035f),Metal);}
  static void Wrench(Transform parent,Vector3 position){var root=new GameObject("Service adjustable wrench").transform;root.SetParent(parent,false);root.localPosition=position;root.localRotation=Quaternion.Euler(0,-33,0);MeshArt.BevelBox(root,"Orange wrench grip",new(0,.02f,-.20f),new(.095f,.065f,.38f),.026f,Orange);MeshArt.BevelBox(root,"Steel wrench shaft",new(0,.028f,.07f),new(.054f,.037f,.26f),.014f,Metal);MeshArt.Tube(root,"Adjustable wrench jaws",new[]{new Vector3(-.07f,.04f,.30f),new Vector3(-.10f,.04f,.20f),new Vector3(0,.04f,.15f),new Vector3(.10f,.04f,.20f),new Vector3(.07f,.04f,.30f)},.032f,Metal,12);MeshArt.Oval(root,"Wrench adjustment screw",new(0,.055f,.17f),new(.07f,.045f,.075f),Navy);}
  static GameObject BuildWorkshop(Transform parent){var root=new GameObject("Modeled company workshop");root.transform.SetParent(parent,false);var wood=MeshArt.Mat("WorkshopPlywood",new(.43f,.30f,.17f));var wall=MeshArt.Mat("WorkshopPlaster",new(.73f,.68f,.57f));MeshArt.Box(root.transform,"Workshop floor",new(0,-.15f,0),new(12,.2f,9),wall);MeshArt.Box(root.transform,"Workshop rear wall",new(0,2.1f,3.5f),new(12,4.2f,.16f),wall);for(int i=0;i<5;i++)MeshArt.Box(root.transform,"Ceiling timber",new(-5+i*2.5f,4.0f,0),new(.15f,.24f,7),wood);VanArt.Text(root.transform,"REPAIR",new(2.2f,3.0f,3.38f),1.0f,new(.025f,.065f,.11f),Quaternion.identity);VanArt.Text(root.transform,"EMPIRE",new(2.2f,2.25f,3.38f),.90f,new(1,.34f,.055f),Quaternion.identity);
   var van=new GameObject("Workshop branded service van");van.transform.SetParent(root.transform,false);van.transform.localPosition=new(-2,0,.4f);van.transform.localRotation=Quaternion.Euler(0,145,0);van.AddComponent<VanArt>().Build();MeshArt.BevelBox(root.transform,"Workshop workbench",new(2.9f,.90f,1.6f),new(4,.15f,1.2f),.025f,wood);for(int i=0;i<3;i++){MeshArt.BevelBox(root.transform,"Navy tool cabinet",new(1.7f+i*1.1f,.44f,1.6f),new(1,.85f,1),.035f,Navy);for(int drawer=0;drawer<4;drawer++)MeshArt.Box(root.transform,"Cabinet chrome handle",new(1.7f+i*1.1f,.2f+drawer*.17f,1.08f),new(.72f,.035f,.04f),Metal);}Wrench(root.transform,new(2.7f,1.0f,1.6f));return root;
  }
 }
}
